<?php
namespace Dth\AccountManagement\Filament\Resources;
use Dth\AccountManagement\Filament\Navigation\AccountManagementNavigationGroup; use Dth\AccountManagement\Filament\Resources\SessionResource\Pages; use Dth\AccountManagement\Models\SessionRecord; use Dth\AccountManagement\Support\AccountAuthorization; use Dth\AccountManagement\Support\UiText; use Filament\Actions; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Model;
class SessionResource extends Resource{protected static ?string $model=SessionRecord::class;protected static string|\BackedEnum|null $navigationIcon='heroicon-o-computer-desktop';protected static string|\UnitEnum|null $navigationGroup=AccountManagementNavigationGroup::Accounts;protected static ?int $navigationSort=50;protected static ?string $slug='account-sessions';public static function getNavigationLabel():string{return UiText::get('navigation.sessions','Phiên đăng nhập');}public static function form(Schema $schema):Schema{return $schema;}public static function table(Table $table):Table{return $table->columns([TextColumn::make('user.name')->label(UiText::get('models.user','Người dùng'))->description(fn(SessionRecord $record):?string=>$record->user?->email)->searchable(),TextColumn::make('ip_address')->label(UiText::get('fields.ip_address','Địa chỉ IP'))->copyable(),TextColumn::make('user_agent')->label(UiText::get('fields.user_agent','Thiết bị / trình duyệt'))->limit(60)->wrap(),TextColumn::make('last_activity')->label(UiText::get('fields.last_activity','Hoạt động gần nhất'))->formatStateUsing(fn($state):string=>date('d/m/Y H:i',(int)$state))->sortable()])->recordActions([Actions\Action::make('revoke')->label(UiText::get('actions.revoke_session','Thu hồi phiên'))->icon('heroicon-o-x-circle')->color('danger')->requiresConfirmation()->action(fn(SessionRecord $record)=>$record->delete())])->defaultSort('last_activity','desc');}public static function getPages():array{return['index'=>Pages\ListSessions::route('/')];}public static function canViewAny():bool{return app(AccountAuthorization::class)->allows('accounts.sessions.manage');}public static function canCreate():bool{return false;}public static function canEdit(Model $record):bool{return false;}public static function canDelete(Model $record):bool{return app(AccountAuthorization::class)->allows('accounts.sessions.manage');}}
